-- Статья 1: Оформление карточки товара
INSERT INTO `news` (`title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `published_at`, `meta_title`, `meta_description`, `meta_keywords`, `og_image`) 
VALUES (
    'Как правильно оформить карточку товара на Авито: полное руководство 2025',
    'kak-oformit-kartochku-tovara-avito-2025',
    'Подробное руководство по созданию продающей карточки товара на Авито. Структура, примеры и рекомендации для увеличения продаж.',
    '<h2>Структура идеальной карточки товара</h2><p>Карточка товара на Авито — это ваша витрина в интернете. От того, насколько грамотно она оформлена, зависит количество просмотров и продаж.</p><h3>1. Заголовок объявления</h3><p><strong>Правило 50 символов:</strong> Заголовок должен быть информативным и содержать:</p><ul><li>Название товара или услуги</li><li>Ключевую характеристику (размер, объем, мощность)</li><li>Преимущество или состояние (новый, комплект, гарантия)</li></ul><p><strong>Примеры хороших заголовков:</strong></p><ul><li>✅ "Диван угловой серый 280см, новый, гарантия 2 года"</li><li>✅ "iPhone 15 Pro 256GB Титан, комплект, чек"</li><li>✅ "Ремонт квартир под ключ, дизайн-проект бесплатно"</li></ul>',
    NULL,
    'published',
    NOW(),
    'Оформление карточки товара на Авито: гид 2025',
    'Узнайте как правильно оформить карточку товара на Авито: структура описания, выбор категории, цены и фото. Советы экспертов для максимальных продаж.',
    'авито карточка товара, оформление объявления авито, как продавать на авито, карточка товара',
    NULL
);

-- Статья 2: Требования к фото
INSERT INTO `news` (`title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `published_at`, `meta_title`, `meta_description`, `meta_keywords`, `og_image`)
VALUES (
    'Требования к фото на Авито: размеры, качество и правила 2025',
    'trebovaniya-k-foto-na-avito-razmery-kachestvo',
    'Технические требования Авито к фотографиям: оптимальные размеры, форматы, вес файлов. Рекомендации для максимального качества и быстрой загрузки.',
    '<h2>Технические требования Авито к фотографиям</h2><h3>Допустимые форматы</h3><ul><li>✅ <strong>JPG/JPEG</strong> — рекомендуется (лучшее сжатие)</li><li>✅ <strong>PNG</strong> — для изображений с прозрачностью</li><li>✅ <strong>GIF</strong> — статичные изображения</li><li>❌ <strong>WebP, HEIC, BMP, TIFF</strong> — не поддерживаются</li></ul><h3>Размеры и разрешение</h3><h4>Рекомендуемые параметры:</h4><ul><li><strong>Разрешение:</strong> 1200×900 пикселей (4:3) или 1280×720 пикселей (16:9)</li><li><strong>Вес файла:</strong> 500-800 КБ</li><li><strong>Качество JPEG:</strong> 85-90%</li></ul>',
    NULL,
    'published',
    DATE_SUB(NOW(), INTERVAL 1 DAY),
    'Требования к фото на Авито: размеры и качество',
    'Полный гид по требованиям Авито к фотографиям: размеры, форматы, вес. Узнайте как подготовить фото для объявлений и избежать отклонения модерацией.',
    'авито требования к фото, размер фото авито, формат фото авито, качество фото',
    NULL
