-- Статья 4: Охранные зоны на фото
INSERT INTO `news` (`title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `published_at`, `meta_title`, `meta_description`, `meta_keywords`, `og_image`)
VALUES (
    'Охранные зоны на фото для Авито: как избежать обрезки важных элементов',
    'oxrannye-zony-na-foto-dlya-avito',
    'Безопасные области на изображениях для Авито: где размещать текст и товар, чтобы ничего не обрезалось в превью и на мобильных устройствах.',
    '<h2>Что такое охранные зоны</h2><p>Охранные зоны — это безопасные области на фотографии, где ключевые элементы (товар, текст, лого) гарантированно будут видны на всех устройствах и в любых форматах отображения.</p><h3>Почему это важно</h3><ul><li>📱 Разные устройства обрезают фото по-разному</li><li>🖼️ Миниатюры в поиске имеют другое соотношение сторон</li><li>💻 Десктоп и мобильная версия показывают разные области</li><li>🔄 Авито может кадрировать фото автоматически</li></ul><h3>Безопасные зоны для Авито</h3><h4>Центральная зона (60% фото)</h4><blockquote>Размещайте здесь:<br>✅ Основной товар<br>✅ Главное фото продукта<br>✅ Ключевые детали</blockquote><h4>Верхняя треть</h4><blockquote>✅ Заголовки и названия<br>✅ Бренд или модель<br>⚠️ Хорошо видна в превью</blockquote><h4>Нижняя треть</h4><blockquote>✅ Дополнительная информация<br>✅ Характеристики<br>⚠️ Может обрезаться на мобильных</blockquote><h3>Опасные зоны (НЕ размещать важное)</h3><ul><li>❌ Крайние 10% по краям — обрезаются в превью</li><li>❌ Углы изображения — теряются при кадрировании</li><li>❌ Самый низ фото — не виден на мобильных</li></ul><h3>Разметка охранных зон</h3><pre><code>┌──────────────────────────────────┐\n│ ░░░░░░ ОПАСНАЯ ЗОНА ░░░░░░░░░░░░ │ ← 10% сверху\n│                                  │\n│  ┌────────────────────────────┐  │\n│  │                            │  │\n│  │   БЕЗОПАСНАЯ ЗОНА 80%      │  │ ← Размещайте товар\n│  │   (товар + основной текст) │  │\n│  │                            │  │\n│  └────────────────────────────┘  │\n│ ░░░░░░ ОПАСНАЯ ЗОНА ░░░░░░░░░░░░ │ ← 10% снизу\n└──────────────────────────────────┘\n   ↑                            ↑\n 10% слева                  10% справа\n</code></pre><h3>Проверка охранных зон</h3><h4>Инструменты:</h4><ul><li><strong>Photoshop:</strong> Просмотр → Направляющие → Новая направляющая (10%, 90%)</li><li><strong>Figma/Sketch:</strong> Layout Grid с отступами 10%</li><li><strong>Онлайн:</strong> SafeFrame Generator</li></ul><h3>Рекомендации по размещению</h3><h4>Для товаров:</h4><ul><li>Товар занимает 60-70% центральной области</li><li>Отступы от краев минимум 10%</li><li>Важные детали в центре кадра</li></ul><h4>Для текста:</h4><ul><li>Заголовок: верхние 20-30% (в безопасной зоне)</li><li>Характеристики: слева или справа (с отступом 15%)</li><li>Дополнительная информация: низ (с отступом 15%)</li></ul><h3>Мобильная адаптация</h3><blockquote><strong>80% пользователей Авито используют мобильные устройства!</strong><br>Всегда проверяйте как фото выглядит на смартфоне.</blockquote><h4>Особенности мобильной версии:</h4><ul><li>Экран вертикальный → обрезаются бока</li><li>Превью меньше → мелкие детали не видны</li><li>Свайп влево/вправо → края попадают в зону жестов</li></ul><h3>Тестирование перед публикацией</h3><ol><li>Откройте фото на компьютере</li><li>Отправьте себе в мессенджер</li><li>Посмотрите на телефоне (вертикально и горизонтально)</li><li>Проверьте виден ли весь товар и текст</li></ol><h3>Частые ошибки</h3><ul><li>❌ Цена в углу фото — обрезается</li><li>❌ Товар упирается в края — теряются детали</li><li>❌ Мелкий текст у края — нечитаем на мобильных</li><li>❌ Важная информация внизу — скрыта кнопками интерфейса</li></ul><h2>Итог</h2><blockquote><strong>Золотое правило:</strong> Вся важная информация должна находиться в центральных 80% изображения с отступами минимум 10% от каждого края.</blockquote>',
    NULL,
    'published',
    DATE_SUB(NOW(), INTERVAL 3 DAY),
    'Охранные зоны на фото Авито: гид по безопасным областям',
    'Полное руководство по охранным зонам на фотографиях Авито. Узнайте где размещать товар и текст, чтобы избежать обрезки на мобильных и в превью.',
    'охранные зоны авито, безопасная зона фото, обрезка фото авито, кадрирование авито',
    NULL
);

-- Статья 5: Подбор фото для объявлений
INSERT INTO `news` (`title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `published_at`, `meta_title`, `meta_description`, `meta_keywords`, `og_image`)
VALUES (
    'Подбор фотографий для объявлений Авито: правила и секреты',
    'podbor-fotografij-dlya-obyavlenij-avito',
    'Как выбрать правильные фото для объявления на Авито: ракурсы, освещение, фон, количество снимков. Профессиональные рекомендации для максимальных продаж.',
    '<h2>Почему важен правильный подбор фото</h2><p>Фотографии — первое, что видит покупатель. Качественные снимки увеличивают шанс продажи на 70% и позволяют продать товар на 15-20% дороже.</p><h3>Количество фотографий</h3><h4>Оптимальное количество: 5-8 фото</h4><ul><li><strong>Минимум 3 фото</strong> — обязательно для нормального объявления</li><li><strong>5-8 фото</strong> — идеально, показывает товар со всех сторон</li><li><strong>10 фото</strong> — максимум на Авито, используйте все слоты</li></ul><h3>Какие ракурсы снимать</h3><h4>Обязательные кадры (первые 5 фото):</h4><ol><li><strong>Главное фото</strong> — общий план, лучший ракурс товара</li><li><strong>Вид спереди</strong> — детальный передний вид</li><li><strong>Вид сбоку</strong> — боковая перспектива</li><li><strong>Вид сзади/сверху</strong> — дополнительный угол</li><li><strong>Детали</strong> — важные элементы крупным планом</li></ol><h4>Дополнительные кадры (6-10 фото):</h4><ul><li>Дефекты и недостатки (если есть)</li><li>Комплектация (все что входит)</li><li>Упаковка (если товар новый)</li><li>Размеры (товар рядом с линейкой)</li><li>Товар в использовании (лайфстайл фото)</li></ul><h3>Освещение</h3><h4>✅ Правильное освещение:</h4><ul><li>Естественный дневной свет (у окна)</li><li>Равномерное освещение без резких теней</li><li>Время съемки: 10:00-16:00</li><li>Облачная погода (мягкий рассеянный свет)</li></ul><h4>❌ Плохое освещение:</h4><ul><li>Вечером при искусственном свете (желтый оттенок)</li><li>Против солнца (темный силуэт)</li><li>Со вспышкой в лоб (блики и пересветы)</li><li>В тени (серое, унылое фото)</li></ul><h3>Фон для съемки</h3><h4>Идеальный фон:</h4><blockquote>Нейтральный, однотонный, без отвлекающих элементов:<br>✅ Белая стена<br>✅ Светлый пол<br>✅ Однотонная ткань (серая, бежевая)<br>✅ Деревянная поверхность (для винтажа)</blockquote><h4>Плохой фон:</h4><ul><li>❌ Грязный ковер</li><li>❌ Немытая посуда в кадре</li><li>❌ Разбросанные вещи</li><li>❌ Яркие обои с узором</li><li>❌ Отражения в зеркале</li></ul><h3>Композиция кадра</h3><h4>Правило третей:</h4><p>Разделите кадр на 9 частей (3×3). Размещайте товар на пересечении линий.</p><pre><code>┌───────┬───────┬───────┐\n│       │       │       │\n├───────┼───────┼───────┤  ← Товар здесь\n│       │ [🎁] │       │\n├───────┼───────┼───────┤\n│       │       │       │\n└───────┴───────┴───────┘\n</code></pre><h4>Ориентация:</h4><ul><li><strong>Горизонтальная (4:3)</strong> — для мебели, техники, недвижимости</li><li><strong>Вертикальная (3:4)</strong> — для одежды, обуви, высоких предметов</li><li><strong>Квадрат (1:1)</strong> — для мелких предметов, украшений</li></ul><h3>Распространенные категории</h3><h4>Одежда и обувь:</h4><ul><li>На модели/манекене (не на полу!)</li><li>Бирка с размером крупным планом</li><li>Детали (пуговицы, молнии, фактура ткани)</li><li>Дефекты (катышки, потертости)</li></ul><h4>Техника и электроника:</h4><ul><li>Включенное устройство (работающий экран)</li><li>Серийный номер</li><li>Разъемы и порты</li><li>Комплектация (коробка, кабели, документы)</li></ul><h4>Мебель:</h4><ul><li>В интерьере (как выглядит в комнате)</li><li>Размеры с рулеткой</li><li>Механизмы (если диван раскладной)</li><li>Обивка крупным планом</li></ul><h4>Автомобили:</h4><ul><li>Три четверти спереди</li><li>Салон (водительское место, задний ряд)</li><li>Приборная панель (пробег)</li><li>Двигатель</li><li>Документы (СТС, ПТС)</li></ul><h3>Постобработка фото</h3><h4>Базовая обработка (рекомендуется):</h4><ul><li>Кадрирование (убрать лишнее)</li><li>Яркость +10-20%</li><li>Контраст +5-10%</li><li>Резкость +10-15%</li><li>Убрать пыль и мелкие дефекты</li></ul><h4>Что НЕ делать:</h4><ul><li>❌ Фильтры Instagram (искажают цвет)</li><li>❌ Размытие фона (выглядит неестественно)</li><li>❌ Сильная ретушь (обман покупателя)</li><li>❌ Добавление графики и эффектов</li></ul><h3>Чек-лист перед публикацией</h3><ul><li>☑️ Минимум 5 фотографий</li><li>☑️ Все ракурсы товара показаны</li><li>☑️ Фото резкие и хорошо освещенные</li><li>☑️ Фон чистый и нейтральный</li><li>☑️ Товар занимает 60-80% кадра</li><li>☑️ Первое фото — самое выигрышное</li><li>☑️ Дефекты показаны честно</li><li>☑️ Размеры фото 1200×900 px</li></ul><h2>Секреты профессионалов</h2><blockquote><strong>Лайфхак:</strong> Снимайте в 2 раза больше фото, чем нужно. Потом выберите лучшие. Первые 3 фото видят 90% покупателей — они должны быть идеальными.</blockquote><p>Правильный подбор и обработка фотографий — это 50% успеха вашего объявления на Авито!</p>',
    NULL,
    'published',
    DATE_SUB(NOW(), INTERVAL 4 DAY),
    'Подбор фото для Авито: профессиональный гид 2025',
    'Как правильно подобрать и сделать фотографии для объявлений Авито: ракурсы, освещение, фон, обработка. Увеличьте продажи с помощью качественных снимков.',
    'подбор фото авито, как фотографировать товар, фото для объявления, съемка товаров',
    NULL
);

SELECT 'Добавлено 5 из 10 статей' AS status;
